import os
from openai import OpenAI

class EmbeddingsClient:
    def __init__(self, api_key=None):
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("OPENAI_API_KEY not found. Please set the environment variable or pass it directly.")
        self.client = OpenAI(api_key=self.api_key)

    def get_client(self):
        return self.client

from embeddings_client import EmbeddingsClient
from embeddings_models import EMBEDDING_MODEL

def embed_batch(payload, config=None):
    client = EmbeddingsClient(api_key=config.get('api_key') if config else None).get_client()
    response = client.embeddings.create(model=EMBEDDING_MODEL, input=payload['texts'])
    return {'embeddings': [item.embedding for item in response.data]}

import math

def similarity_score(payload):
    embedding1 = payload['embedding1']
    embedding2 = payload['embedding2']

    dot_product = sum(e1 * e2 for e1, e2 in zip(embedding1, embedding2))
    magnitude1 = math.sqrt(sum(e**2 for e in embedding1))
    magnitude2 = math.sqrt(sum(e**2 for e in embedding2))

    if not magnitude1 or not magnitude2:
        return 0.0

    return dot_product / (magnitude1 * magnitude2)

from embeddings_client import EmbeddingsClient
from embeddings_models import TRANSLATION_MODEL # Using a general purpose model for summarization

def embedding_job_summary(payload, config=None):
    client = EmbeddingsClient(api_key=config.get('api_key') if config else None).get_client()

    job_results = payload['job_results']
    prompt = f"Summarize the following embedding job results:\n\n{job_results}"

    response = client.chat.completions.create(
        model=TRANSLATION_MODEL, # Using a general purpose model like gpt-3.5-turbo for summarization
        messages=[
            {"role": "system", "content": "You are a helpful assistant that summarizes text."}, 
            {"role": "user", "content": prompt}
        ]
    )
    return {'summary': response.choices[0].message.content}

from embeddings_client import EmbeddingsClient
from embeddings_models import TRANSLATION_MODEL

def multilingual_query_translate(payload, config=None):
    client = EmbeddingsClient(api_key=config.get('api_key') if config else None).get_client()

    query = payload['query']
    target_language = payload.get('target_language', 'English')

    prompt = f"Translate the following query into {target_language}: {query}"

    response = client.chat.completions.create(
        model=TRANSLATION_MODEL,
        messages=[
            {"role": "system", "content": f"You are a helpful assistant that translates text into {target_language}."},
            {"role": "user", "content": prompt}
        ]
    )
    return {'translated_query': response.choices[0].message.content}
